        path = self._find_skill_path(name)
        if not path.exists():
            await self.edit(event, self.strings("skill_not_found"))
            return
        path.unlink()
        try:
            if path.name == "SKILL.md" and not any(path.parent.iterdir()):
                path.parent.rmdir()
        except Exception:
            pass
        await self.edit(
            event,
            self.strings(
                "skill_deleted", name=html.escape(self._skill_name_from_path(path))
            ),
            as_html=True,
        )

